package com.example.simpleaccountant.ui.transactions;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.TransactionDao;import com.example.simpleaccountant.data.model.Transaction;import com.example.simpleaccountant.util.Constants;import com.example.simpleaccountant.util.DateUtils;
public class AddTransactionActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_transaction);TransactionDao dao=new TransactionDao(this);EditText title=findViewById(R.id.etTitle),amount=findViewById(R.id.etAmount),date=findViewById(R.id.etDate),note=findViewById(R.id.etNote);Spinner type=findViewById(R.id.spType),cat=findViewById(R.id.spCategory),pm=findViewById(R.id.spPaymentMethod);date.setText(DateUtils.today());String preset=getIntent().getStringExtra("type");if(preset!=null){type.setSelection(Constants.TYPE_EXPENSE.equals(preset)?1:0);}ArrayAdapter<String> ta=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"INCOME","EXPENSE"});type.setAdapter(ta);cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Sales","Service","Salary","Investment","Rent","Electricity","Other"}));pm.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"CASH","CARD","BANK_TRANSFER","OTHER"}));findViewById(R.id.btnSave).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("Required");return;}double a;try{a=Double.parseDouble(amount.getText().toString().trim());}catch(Exception e){amount.setError("Invalid amount");return;}if(a<=0){amount.setError("Must be > 0");return;}if(date.getText().toString().trim().isEmpty()){date.setError("Required");return;}Transaction t=new Transaction();t.setTitle(title.getText().toString().trim());t.setAmount(a);t.setType(type.getSelectedItem().toString());t.setCategory(cat.getSelectedItem().toString());t.setPaymentMethod(pm.getSelectedItem().toString());t.setTransactionDate(date.getText().toString().trim());t.setNote(note.getText().toString().trim());dao.insertTransaction(t);Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();finish();}); }}
